DROP TABLE IF EXISTS `categories`;
CREATE TABLE "categories" ("id" integer not null primary key autoincrement, "slug" varchar not null, "nom" varchar not null, "couleur" varchar not null, "created_at" datetime, "updated_at" datetime);


DROP TABLE IF EXISTS `questions`;
CREATE TABLE "questions" ("id" integer not null primary key autoincrement, "categorie_id" integer not null, "question" varchar not null, "bonne_reponse" varchar not null, "mauvaise_1" varchar not null, "mauvaise_2" varchar not null, "mauvaise_3" varchar not null, "difficulte" varchar not null default 'moyen', "created_at" datetime, "updated_at" datetime, foreign key("categorie_id") references "categories"("id") on delete cascade);


DROP TABLE IF EXISTS `parties`;
CREATE TABLE "parties" ("id" integer not null primary key autoincrement, "pseudo" varchar not null, "categorie_id" integer, "difficulte" varchar not null, "mode" varchar not null default 'solo', "score" integer not null, "total" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("categorie_id") references "categories"("id") on delete set null);


